import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation that efficiently determines if an item is in a set with a possibility of false positives.
    It uses a bit array and multiple hash functions to achieve space-efficient membership checking.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array (m)
        self.size = self._get_bit_array_size(expected_items, false_positive_rate)

        # Calculate the optimal number of hash functions (k)
        self.hash_count = self._get_hash_count(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    @staticmethod
    def _get_bit_array_size(n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    @staticmethod
    def _get_hash_count(m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> int:
        """Generate hash values for an item using multiple hash functions."""
        hash_vals = set()
        for i in range(self.hash_count):
            hash_object = hashlib.md5(f"{item}{i}".encode())
            hash_value = int(hash_object.hexdigest(), 16) % self.size
            hash_vals.add(hash_value)
        return hash_vals

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._hashes(item))

