    @staticmethod
    def _calculate_hash_count(m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _fibonacci_hash(self, item: str, i: int) -> int:
        """Generate a hash value using a Fibonacci hashing approach."""
        hash_code = int(hashlib.sha256(item.encode()).hexdigest(), 16)
        fib_hash = (hash_code + (i * self._fibonacci(i))) % self.size
        return fib_hash

    def _fibonacci(self, n: int) -> int:
        """Calculate the n-th Fibonacci number."""
        a, b = 0, 1
        for _ in range(n):
            a, b = b, a + b
        return a

    def _get_hashes(self, item: str) -> list:
        """Generate distinct hash values for an item using Fibonacci hashing."""
        return [self._fibonacci_hash(item, i) for i in range(self.hash_count)]

