import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and implements a hash function strategy 
    based on XOR and modular arithmetic to provide a probabilistic membership test with controlled 
    false positive rates and efficient bit manipulation.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._compute_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._compute_hash_count(self.size, expected_items)

        self.bit_array = [0] * self.size

    @staticmethod
    def _compute_bit_array_size(n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    @staticmethod
    def _compute_hash_count(m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _xor_hash(self, item: str, seed: int) -> int:
        """Generate a hash value using XOR and modular arithmetic."""
        hash_value = 0
        item_bytes = item.encode('utf-8')

        for b in item_bytes:
            hash_value ^= (b + seed) % self.size

        return hash_value % self.size

    def _get_hashes(self, item: str) -> list:
        """Generate multiple hash values for an item."""
        return [self._xor_hash(item, i) for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._get_hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._get_hashes(item))
